package io.github.jubasse.seampact.springboot.runtime;

import java.math.BigInteger;
import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * The boundary's first step, before its table is read (ADR 0025, G3): the version the api's generated code carries
 * against this runtime's. The runtime serves the code of its own `major.minor` written by a generator at its patch or
 * an earlier one.
 */
public final class GeneratorVersionCheck {
    /** The rule id of a boot refused for code generated by another version. */
    public static final String GENERATED_FOR_OTHER_VERSION = "runtime.generated-for-other-version";

    private static final Pattern RELEASE_VERSION = Pattern.compile("(\\d+)\\.(\\d+)\\.(\\d+)");

    private GeneratorVersionCheck() {
    }

    /** The problem of an api generated by a version [installedVersion] does not serve; empty when it serves it. */
    public static Optional<String> problem(String apiId, String generatedVersion, String installedVersion) {
        if (serves(installedVersion, generatedVersion)) return Optional.empty();

        return Optional.of(GENERATED_FOR_OTHER_VERSION + ": The `" + apiId + "` boundary was generated by seampact `" + generatedVersion
                + "`; the installed runtime is `" + installedVersion + "`; fix: run the seampact generate task again (Gradle"
                + " `seampactGenerate`, Maven `seampact:generate`) with the plugin at `" + installedVersion
                + "`, or install seampact-spring-runtime at `" + generatedVersion + "` or a later patch of it.");
    }

    // The same version serves; otherwise both are release versions of one `major.minor` and the runtime's patch is at
    // or above the generator's. A prerelease version serves only itself.
    private static boolean serves(String installedVersion, String generatedVersion) {
        if (installedVersion.equals(generatedVersion)) return true;

        Matcher installed = RELEASE_VERSION.matcher(installedVersion);
        Matcher generated = RELEASE_VERSION.matcher(generatedVersion);
        if (!installed.matches() || !generated.matches()) return false;

        return installed.group(1).equals(generated.group(1))
                && installed.group(2).equals(generated.group(2))
                && new BigInteger(installed.group(3)).compareTo(new BigInteger(generated.group(3))) >= 0;
    }
}
